/**
 * Moves every issue from the source label to the target label and deletes the
 * source, atomically. Returns null (changing nothing) if either label is
 * missing from the org.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<{ label: IssueLabel; issuesRelabelled: number } | null> {
  return getDb().transaction((tx) => {
    const find = (id: LabelId) =>
      tx
        .select()
        .from(labels)
        .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, id)))
        .get();
    const source = find(sourceLabelId);
    const target = find(targetLabelId);
    if (!source || !target) return null;

    const sourceRows = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all();

    if (sourceRows.length > 0) {
      tx.insert(issueLabels)
        .values(
          sourceRows.map((r) => ({
            orgId,
            issueId: r.issueId,
            labelId: targetLabelId,
          })),
        )
        .onConflictDoNothing()
        .run();
    }
    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return { label: toLabel(target), issuesRelabelled: sourceRows.length };
  });
}
